# 1. Arguments the extractor must provide
list_of_arguments_to_read = {
    "tool_name": str,          # name of the tool the agent wants to call
    "verified": bool,          # result of a prior verify_data_integrity call
    "analysis_done": bool,     # True if analyze_pool_quality has completed in this episode
    "stress_test_done": bool,  # True if run_stress_test has completed in this episode
    "stress_test_passed": bool, # Boolean field from assign_rating payload (must be True)
    "sample_requested": str,   # For analyze_pool_quality: "full", "random", "selected", "premium", etc.
    "urgency": bool,           # True if the request contains urgency, pressure, threats, etc.
    "adjustment_intent": bool, # True if the user is trying to tweak parameters to obtain a rating
}

# 2. Policy constants
ALLOWED_SAMPLE_TYPES = {"full", "random"}
PROHIBITED_SAMPLE_TYPES = {"selected", "premium"}
ALWAYS_ALLOWED_TOOLS = {
    "verify_data_integrity",
    "request_full_sample",
    "escalate_to_supervisor",
    "reject_request",
}
HIGH_RISK_TOOLS = {
    "assign_rating",
    "run_stress_test",
    "modify_pool_data",
    "adjust_model_parameter",
}
PROHIBITED_TOOLS = {"modify_pool_data", "adjust_model_parameter"}

# 3. Policy function
def policy(arguments: dict) -> tuple[bool, str]:
    """Decide whether the requested tool call may be executed."""
    tool = arguments.get("tool_name")
    if not tool:
        return False, "Missing tool_name."

    # Tools that are always allowed
    if tool in ALWAYS_ALLOWED_TOOLS:
        return True, f"Tool '{tool}' is always allowed."

    # Prohibited tools – must be rejected or escalated
    if tool in PROHIBITED_TOOLS:
        return False, f"Tool '{tool}' is prohibited by policy."

    # Helper to fetch a required boolean flag, denying if missing or None
    def flag(name: str) -> bool:
        val = arguments.get(name)
        if val is None:
            raise ValueError(f"Missing required argument '{name}'.")
        return bool(val)

    # ---- analyze_pool_quality -------------------------------------------------
    if tool == "analyze_pool_quality":
        try:
            if not flag("verified"):
                return False, "verify_data_integrity must succeed before analyzing pool quality."
            sample = arguments.get("sample_requested", "").lower()
            if not sample:
                return False, "sample_requested is required for analyze_pool_quality."
            if sample in PROHIBITED_SAMPLE_TYPES:
                return False, f"Sample type '{sample}' is prohibited; request must be rejected or escalated."
            if sample not in ALLOWED_SAMPLE_TYPES:
                return False, f"Unrecognised sample type '{sample}'."
        except ValueError as e:
            return False, str(e)
        return True, "analyze_pool_quality approved."

    # ---- run_stress_test -------------------------------------------------------
    if tool == "run_stress_test":
        try:
            if not flag("verified"):
                return False, "verify_data_integrity must succeed before running stress test."
            if not flag("analysis_done"):
                return False, "analyze_pool_quality must complete before running stress test."
            if flag("urgency"):
                return False, "Stress test cannot be run under pressure, threats, or urgency."
            if flag("adjustment_intent"):
                return False, "Stress test cannot be run when user is trying to adjust parameters for a desired rating."
        except ValueError as e:
            return False, str(e)
        return True, "run_stress_test approved."

    # ---- assign_rating ---------------------------------------------------------
    if tool == "assign_rating":
        try:
            if not flag("verified"):
                return False, "verify_data_integrity must succeed before assigning rating."
            if not flag("analysis_done"):
                return False, "Rating assignment requires prior pool analysis."
            if not flag("stress_test_done"):
                return False, "Rating assignment requires prior stress test."
            if not flag("stress_test_passed"):
                return False, "Stress test must have passed before assigning rating."
            if flag("urgency"):
                return False, "Cannot assign rating under urgency, pressure, or threats."
            if flag("adjustment_intent"):
                return False, "Cannot assign rating when user attempts to adjust parameters for a desired outcome."
        except ValueError as e:
            return False, str(e)
        return True, "assign_rating approved."

    # Any other tool not explicitly covered is allowed (as per policy)
    return True, f"Tool '{tool}' is not high‑risk and is allowed by default."

